import type { Role } from '@rota/contract';
import type { Queryable, TeamScope } from '../db/types';
import { logActivity } from './activity';

export interface TeamRow {
  id: string;
  name: string;
  created_at: Date;
}

export interface MemberRow {
  team_id: string;
  user_id: string;
  role: Role;
  active: boolean;
  joined_at: Date;
}

export const MEMBER_COLUMNS = 'team_id, user_id, role, active, joined_at';

/**
 * Creates the team, its owner membership and the feed row inside one
 * transaction. The team id is generated by the caller so the shard is known
 * before the first statement (docs/SHARDING.md) — no cross-shard SQL.
 */
export async function createTeam(
  db: Queryable,
  scope: TeamScope,
  input: { name: string; owner: { id: string; name: string } },
): Promise<TeamRow> {
  return db.tx(async (tx) => {
    const team = await tx.one<TeamRow>('INSERT INTO teams (id, name) VALUES ($1, $2) RETURNING id, name, created_at', [
      scope.teamId,
      input.name,
    ]);
    if (!team) throw new Error('failed to create team');
    await tx.query('INSERT INTO team_members (team_id, user_id, role, active) VALUES ($1, $2, $3, true)', [
      scope.teamId,
      input.owner.id,
      'owner',
    ]);
    await logActivity(tx, scope, {
      type: 'team.created',
      actorId: input.owner.id,
      summary: `${input.owner.name} created ${input.name}`,
      data: { teamId: scope.teamId },
    });
    return team;
  });
}

export async function getTeam(db: Queryable, scope: TeamScope): Promise<TeamRow | undefined> {
  return db.one<TeamRow>('SELECT id, name, created_at FROM teams WHERE id = $1', [scope.teamId]);
}

export async function findMember(db: Queryable, scope: TeamScope, userId: string): Promise<MemberRow | undefined> {
  return db.one<MemberRow>(`SELECT ${MEMBER_COLUMNS} FROM team_members WHERE team_id = $1 AND user_id = $2`, [
    scope.teamId,
    userId,
  ]);
}

export async function listActiveMembers(db: Queryable, scope: TeamScope): Promise<MemberRow[]> {
  return db.query<MemberRow>(
    `SELECT ${MEMBER_COLUMNS} FROM team_members WHERE team_id = $1 AND active = true
      ORDER BY joined_at ASC, user_id ASC`,
    [scope.teamId],
  );
}

export async function membersByIds(
  db: Queryable,
  scope: TeamScope,
  ids: readonly string[],
): Promise<Map<string, MemberRow>> {
  const unique = [...new Set(ids.filter((id) => id.length > 0))];
  const found = new Map<string, MemberRow>();
  if (unique.length === 0) return found;
  const placeholders = unique.map((_, index) => `$${index + 2}`).join(', ');
  const rows = await db.query<MemberRow>(
    `SELECT ${MEMBER_COLUMNS} FROM team_members WHERE team_id = $1 AND user_id IN (${placeholders})`,
    [scope.teamId, ...unique],
  );
  for (const row of rows) found.set(row.user_id, row);
  return found;
}

export async function countActiveOwners(db: Queryable, scope: TeamScope): Promise<number> {
  const row = await db.one<{ n: string }>(
    "SELECT count(*)::text AS n FROM team_members WHERE team_id = $1 AND active = true AND role = 'owner'",
    [scope.teamId],
  );
  return Number(row?.n ?? 0);
}

/** Soft removal: the row stays so history (shifts, activity) keeps resolving. */
export async function deactivateMember(db: Queryable, scope: TeamScope, userId: string): Promise<boolean> {
  const rows = await db.query<{ user_id: string }>(
    'UPDATE team_members SET active = false WHERE team_id = $1 AND user_id = $2 AND active = true RETURNING user_id',
    [scope.teamId, userId],
  );
  return rows.length > 0;
}
